}

.editorial-card:hover .editorial-image {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.editorial-category {
    display: inline-block;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--accent-color);
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.editorial-title {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    color: var(--primary-color);
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--text-light);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.read-more {
    color: var(--accent-color);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.read-more:hover {
    color: var(--primary-color);
}

/* ===== Newsletter Section ===== */
.newsletter {
    background: linear-gradient(135deg, #1a1a1a 0%, #404040 100%);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) 0;
}

.newsletter-content {
    text-align: center;
}

.newsletter h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
}

.newsletter p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-md);
    max-width: 500px;
    margin: 0 auto;
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 200px;
    padding: 12px 16px;
    border: 1px solid var(--border-light);
    border-radius: var(--radius-md);
    background-color: var(--secondary-color);
    color: var(--primary-color);
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: var(--text-light);
}

.newsletter-btn {
    white-space: nowrap;
    min-width: 120px;
}

/* ===== Footer ===== */
.footer {
    background-color: var(--primary-color);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) 0 var(--spacing-lg);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-section h4 {
    margin-bottom: var(--spacing-md);
    font-size: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--border-light);
    text-decoration: none;
    transition: color var(--transition);
}

.footer-section a:hover {
    color: var(--accent-color);
}

.footer-bottom {
    border-top: 1px solid var(--border-dark);
    padding-top: var(--spacing-lg);
    text-align: center;
    color: var(--border-light);
    font-size: 0.9rem;
}

/* ===== Responsive Design ===== */
@media (max-width: 768px) {
    .hero-title {
        font-size: 2.5rem;
    }

    .hero-subtitle {
        font-size: 1.1rem;
    }

    .nav-links {
        gap: var(--spacing-lg);
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: var(--spacing-md);
    }

    .section-header h2 {
        font-size: 2rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-btn {
        width: 100%;
    }
}

@media (max-width: 640px) {
    .logo {
        font-size: 1.2rem;
    }

    .nav-links {
        display: none;
    }

    .hero {
        height: 400px;
    }

    .hero-title {
        font-size: 2rem;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;
    }
}
