    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
    color: var(--primary-color);
}

.product-category {
    font-size: 0.9rem;
    color: var(--text-light);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-md);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    margin-bottom: var(--spacing-md);
    font-size: 0.9rem;
}

.stars {
    color: var(--accent-color);
}

.rating-count {
    color: var(--text-light);
}

.product-price {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-md);
}

.price-current {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-color);
}

.price-original {
    font-size: 1rem;
    color: var(--text-light);
    text-decoration: line-through;
}

.add-to-cart-btn {
    width: 100%;
    padding: 12px;
    margin-top: auto;
}

/* ===== Deals Section ===== */
.deals-banner {
    background: linear-gradient(135deg, var(--accent-light) 0%, #f0d99f 100%);
    padding: var(--spacing-2xl) 0;
}

.deals-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

.deals-banner h2 {
    font-size: 2.5rem;
    color: var(--primary-color);
    margin-bottom: var(--spacing-2xl);
    text-align: center;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-xl);
}

.deal-card {
    background: var(--secondary-color);
    border-radius: var(--radius-lg);
    padding: var(--spacing-xl);
    box-shadow: var(--shadow-md);
    position: relative;
    transition: var(--transition);
    text-align: center;
}

.deal-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.deal-badge {
    position: absolute;
    top: -12px;
    left: 50%;
    transform: translateX(-50%);
    background-color: var(--success-color);
    color: var(--secondary-color);
