    .hero-subtitle {
        font-size: 1.1rem;
    }

    .nav-links {
        gap: var(--spacing-lg);
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: var(--spacing-md);
    }

    .section-header h2 {
        font-size: 2rem;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
